journals = sa.table(
    'journals', sa.column('title', sa.Text), sa.column('base', sa.String), sa.column('description', sa.Text),
)


def _same(column, value):
    return column.is_(None) if value is None else column == value


def upgrade() -> None:
    # Admin /shelf orqali o'zgartirgan qiymatlarga tegmaymiz — faqat eski qiymat turgan bo'lsa yangilanadi
    for title, old_base, new_base, old_desc, new_desc in JOURNALS:
        if new_base != old_base:
            op.execute(journals.update()
                       .where(journals.c.title == title, journals.c.base == old_base).values(base=new_base))
        op.execute(journals.update()
                   .where(journals.c.title == title, _same(journals.c.description, old_desc))
                   .values(description=new_desc))


def downgrade() -> None:
    for title, old_base, new_base, old_desc, new_desc in JOURNALS:
        if new_base != old_base:
            op.execute(journals.update()
                       .where(journals.c.title == title, journals.c.base == new_base).values(base=old_base))
        op.execute(journals.update()
                   .where(journals.c.title == title, journals.c.description == new_desc)
                   .values(description=old_desc))
